import {
	Accessor,
	Component,
	createEffect,
	createMemo,
	createSignal,
	For,
	Match,
	onCleanup,
	onMount,
	Setter,
	Show,
	Switch,
	useContext,
} from "solid-js";

import ActionHandler from "#core/ui/input/action-handler.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { Divider } from "#core/ui-next/components/divider.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { VSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";

import {
	LaunchpadStatus,
	PlayerScienceDetail,
	ScienceDetailProps,
	ScienceDetailStarInfo,
	useVictoriesScreenContext,
	VictoryTabType,
} from "#base/ui-next/screens/victories/victories-screen-model.js";
import {
	VictoryCountdownBar,
	VictoryCountdownBarProps,
	VictoryCountdownPlayer,
} from "#base/ui-next/screens/victories/victory-countdown-bar.jsx";
import { VictoryHeader, VictoryRow, VictoryTabBase } from "#base/ui-next/screens/victories/victory-tab-base.jsx";
import { ScienceVictoryItemTooltip } from "#base/ui-next/tooltips/science-victory-item-tooltip.jsx";
interface PointMarkerProps {
	points: number;
}
const PointMarkerComponent: Component<PointMarkerProps> = (props) => {
	return (
		<div class="flex flex-col items-center w-1 text-accent">
			<div>{props.points}</div>
			<Divider.Vertical length="2" />
		</div>
	);
};
//#endregion

//#region Points Bar Item
interface PointsBarItemProps {
	playerId: PlayerId;
	starInfo: ScienceDetailStarInfo;
	playerHighlighted: boolean;
	anyStarHighlighted: Accessor<boolean>;
	setAnyStarHighlighted: Setter<boolean>;
}
const PointsBarItem: Component<PointsBarItemProps> = (props) => {
	const model = useVictoriesScreenContext();

	const [starHighlighted, setStarHighlighted] = createSignal(false);

	const starScale = createMemo(() => {
		if (props.starInfo.pointsValue < 5) {
			return 0.5;
		}
		if (props.starInfo.pointsValue < 10) {
			return props.starInfo.pointsValue / 10;
		}
		return 1;
	});
	const getScale = () => {
		return props.playerHighlighted ? 1.5 : 1;
	};

	return (
		<div
			class="absolute size-6 -translate-x-1\/2"
			style={{ left: `${Math.min(100, props.starInfo.accumulatedPoints)}%` }}
		>
			<ScienceVictoryItemTooltip {...props.starInfo}>
				<Activatable
					class="duration-150 ease-out"
					classList={{ "opacity-70": props.anyStarHighlighted() && !starHighlighted() }}
					style={{
						transform: `scale(${getScale()})`,

						"transition-property": "transform, opacity",
					}}
					onMouseEnter={() => {
						setStarHighlighted(true);
						props.setAnyStarHighlighted(true);
					}}
					onMouseLeave={() => {
						setStarHighlighted(false);
						props.setAnyStarHighlighted(false);
					}}
					onFocus={() => {
						setStarHighlighted(true);
						props.setAnyStarHighlighted(true);
						model.focusPlayer(props.playerId, VictoryTabType.Scientific);
					}}
					onBlur={() => {
						setStarHighlighted(false);
						props.setAnyStarHighlighted(false);
						model.unFocusPlayer(props.playerId, VictoryTabType.Scientific);
					}}
				>
					<div
						class="size-6 bg-center bg-contain bg-no-repeat"
						style={{
							"background-image": "url(blp:victory_science_star01)",
							transform: `scale(${starScale()})`,
						}}
					/>
					<Show when={props.starInfo.pointsValue >= 10}>
						<div
							class="absolute size-6 bg-center bg-contain bg-no-repeat"
							style={{
								"background-image": "url(blp:victory_science_star02)",
							}}
						/>
					</Show>
				</Activatable>
			</ScienceVictoryItemTooltip>
		</div>
	);
};
//#endregion

//#region Points Bar
interface PointsBarProps {
	playerDetail: PlayerScienceDetail;
	pointsSectionHeaders: number[];
}
const PointsBarComponent: Component<PointsBarProps> = (props) => {
	const model = useVictoriesScreenContext();
	const [anyStarHighlighted, setAnyStarHighlighted] = createSignal(false);
	const barPercent = createMemo(() => {
		// If the player has at least 100 Innovation Points but hasn't build a launch pad, show the bar at its highest displayable point
		const launchpadStatus = props.playerDetail.launchpadStatus.status;
		if (
			props.playerDetail.playerInfo.score >= 100 &&
			launchpadStatus !== LaunchpadStatus.Built &&
			launchpadStatus !== LaunchpadStatus.InUse
		) {
			return 99.9;
		}
		if (props.playerDetail.playerInfo.score > model.data.scienceDetails.targetScore) {
			return 100;
		}
		if (model.data.scienceDetails.targetScore === 0) {
			return 0;
		}
		return Math.round((props.playerDetail.playerInfo.score / model.data.scienceDetails.targetScore) * 100);
	});

	return (
		<div class="flex-auto flex flex-row relative">
			<div class="flex flex-row absolute inset-0">
				<For each={props.pointsSectionHeaders}>
					{(_) => (
						<div class="flex-auto flex flex-col justify-center">
							<Divider.Vertical
								class="-translate-x-1\/2"
								length="3\/4"
							/>
						</div>
					)}
				</For>
				<div class="flex flex-col justify-center">
					<Divider.Vertical
						class="-translate-x-1\/2"
						length="3\/4"
						color="white"
					/>
				</div>
			</div>
			<div
				class=" flex flex-row items-center relative"
				style={{ "flex-basis": `${barPercent()}%` }}
			>
				<div
					class="flex-auto h-8"
					classList={{ "mr-12": barPercent() < 100 }}
					style={{
						"background-color": props.playerDetail.barColor,
						border: barPercent() > 0 ? "solid 2px rgba(127, 127, 127, 0.5)" : "none",
					}}
				/>
				<Show when={barPercent() !== 100}>
					<div class="h-12 w-18 -right-1 z-1 absolute pointer-events-none">
						<div
							class="size-full bg-center bg-contain bg-no-repeat absolute duration-150 ease-out"
							style={{
								"background-image": "url(blp:icon_victory_science_rocket)",
								// eslint-disable-next-line solid/style-prop
								"fxs-background-image-tint": props.playerDetail.playerInfo.highlighted()
									? props.playerDetail.fadedRocketColor
									: props.playerDetail.rocketColor,
								"transition-property": "fxs-background-image-tint",
							}}
						/>
						<div
							class="size-full bg-center bg-contain bg-no-repeat absolute duration-150 ease-out"
							classList={{ "opacity-30": props.playerDetail.playerInfo.highlighted() }}
							style={{
								"background-image": "url(blp:icon_victory_science_rocket_stroke)",
								"transition-property": "opacity",
							}}
						/>
					</div>
				</Show>
			</div>
			<div class="flex flex-row absolute inset-0 items-center">
				<For each={props.playerDetail.starInfo}>
					{(star) => (
						<Show when={star.accumulatedPoints < model.data.scienceDetails.targetScore}>
							<PointsBarItem
								starInfo={star}
								playerId={props.playerDetail.playerInfo.playerId}
								anyStarHighlighted={anyStarHighlighted}
								setAnyStarHighlighted={setAnyStarHighlighted}
								playerHighlighted={props.playerDetail.playerInfo.highlighted()}
							/>
						</Show>
					)}
				</For>
			</div>
		</div>
	);
};
//#endregion

//#region Launchpad display
interface LaunchpadProps {
	launchpadStatus: { status: LaunchpadStatus; tooltipHeader: string; tooltipText: string };
	rocketColor: string;
}

const LaunchpadDisplayComponent: Component<LaunchpadProps> = (props) => {
	return (
		<div class="flex flex-col items-center justify-center">
			<div class="size-14">
				<Switch>
					<Match when={props.launchpadStatus.status === LaunchpadStatus.PreModern}>
						<Icon
							class="size-full"
							name="url(blp:victory_science_launchpad01)"
							isUrl
						/>
					</Match>
					<Match when={props.launchpadStatus.status === LaunchpadStatus.NeedRocketry}>
						<Icon
							class="size-full"
							name="url(blp:victory_science_launchpad02)"
							isUrl
						/>
					</Match>
					<Match when={props.launchpadStatus.status === LaunchpadStatus.NotBuilt}>
						<Icon
							class="size-full"
							name="url(blp:victory_science_launchpad03)"
							isUrl
						/>
					</Match>
					<Match when={props.launchpadStatus.status === LaunchpadStatus.Built}>
						<Icon
							class="size-full"
							name="url(blp:victory_science_launchpad04)"
							isUrl
						/>
					</Match>
					<Match when={props.launchpadStatus.status === LaunchpadStatus.InUse}>
						<div class="relative size-full">
							<Icon
								class="size-full"
								name="url(blp:victory_science_launchpad04)"
								isUrl
							/>
							<div
								class="size-full bg-center bg-contain bg-no-repeat absolute"
								style={{
									"background-image": "url(blp:victory_science_launchpad05)",
									// eslint-disable-next-line solid/style-prop
									"fxs-background-image-tint": props.rocketColor,
								}}
							/>
							<Icon
								class="size-full absolute"
								name="url(blp:victory_science_launchpad05_stroke)"
								isUrl
							/>
						</div>
					</Match>
					<Match when={props.launchpadStatus.status === LaunchpadStatus.Damaged}>
						<Icon
							class="size-full"
							name="url(blp:victory_science_launchpad06)"
							isUrl
						/>
					</Match>
				</Switch>
			</div>
		</div>
	);
};
//#endregion

const ScienceVictoryTabComponent: Component<ScienceDetailProps> = (props) => {
	const model = useVictoriesScreenContext();
	const victoryCountdownBarProps = createMemo<VictoryCountdownBarProps>(() => {
		const victoryBarPlayers: VictoryCountdownPlayer[] = props.playerDetails.map((playerDetail) => ({
			playerInfo: playerDetail.playerInfo,
			countdownProgress: playerDetail.countdownProgress,
			launchpadDamaged: playerDetail.launchpadStatus.status === LaunchpadStatus.Damaged,
		}));
		return { players: victoryBarPlayers, countdownDuration: props.countdownDuration };
	});
	const hotkeyContext = useContext(HotkeyContext);

	onMount(() => {
		hotkeyContext.registerNavtray("shell-action-3", "LOC_VICTORY_NAV_HELP_RULES");
		model.tabNavStartup(hotkeyContext);
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("shell-action-3");
		model.tabNavShutdown(hotkeyContext);
	});

	const [isHighlightingAnyone, setIsHighlightingAnyone] = createSignal<boolean>(false);

	createEffect(() => {
		setIsHighlightingAnyone(
			props.playerDetails.some((player) => {
				return player.playerInfo.highlighted();
			}),
		);
	});

	function onFocus(playerId: PlayerId) {
		model.focusPlayer(playerId, VictoryTabType.Scientific);
	}

	function onBlur(playerId: PlayerId) {
		model.unFocusPlayer(playerId, VictoryTabType.Scientific);
	}

	return (
		<VictoryTabBase
			header={model.data.scienceDetails.headerText}
			titleColorClass={model.data.panels[3].titleColor}
			background={model.data.panels[3].background}
			targetScore={model.data.scienceDetails.targetScore}
			title="LOC_VICTORY_SCIENCE_MODERN_NAME"
			rules="LOC_VICTORIES_RULES_SCIENTIFIC"
			pointsNeededText="LOC_INNOVATION_POINTS_NEEDED_TO_WIN"
			showPointsNeeded={
				model.data.scienceDetails.shortestRemainingCountdownDuration >=
				model.data.scienceDetails.countdownDuration
			}
			alternatePointsContent={
				<Show
					when={
						!(
							Game.AgeProgressManager.isExtendedGame ||
							Game.AgeProgressManager.getMaxAgeProgressionPoints() <= 0
						)
					}
					fallback={<div class="h-8 victories-military-col-3" />}
				>
					<div class="flex-1 font-body text-lg text-white flex flex-col mb-2 items-end">
						<div class="mr-2 w-full">
							<div class="uppercase font-title text-lg self-end">
								<L10n.Stylize
									text="LOC_VICTORIES_COUNTDOWN_LABEL"
									args={[model.data.scienceDetails.shortestRemainingCountdownDuration]}
								/>
							</div>
							<div class="self-end">
								<VictoryCountdownBar {...victoryCountdownBarProps()} />
							</div>
						</div>
					</div>
				</Show>
			}
			preScrollContent={
				<div class="relative flex flex-col self-start items-center w-full">
					<VictoryHeader
						showDividersAroundChildren={false}
						childContainerPosition="end"
					>
						<div class="flex flex-row">
							<div class="flex-auto flex flex-row self-end">
								<div class="w-22" />
								<For each={props.pointsSectionHeaders}>
									{(points) => (
										<div class="flex-auto">
											<PointMarkerComponent points={points} />
										</div>
									)}
								</For>
								<PointMarkerComponent points={model.data.scienceDetails.targetScore} />
								<div class="w-22" />
								<div class="w-9" />
							</div>
						</div>
					</VictoryHeader>
				</div>
			}
		>
			<VSlot
				class="relative flex flex-col items-start"
				lockNavigation={true}
				autoFocus={!model.tooltipToggle}
			>
				<For each={props.playerDetails}>
					{(player, index) => {
						const launchpadProps = createMemo(() => ({
							launchpadStatus: player.launchpadStatus,
							rocketColor: player.rocketColor,
						}));

						return (
							<VSlot
								class="victories-scientific-focus transition-opacity duration-150 ease-out w-full"
								classList={{
									"opacity-50": isHighlightingAnyone() && player.playerInfo.highlighted() === false,
								}}
							>
								<VictoryRow
									rowId={index() + 1}
									playerInfo={player.playerInfo}
									divider={false}
									rowType={VictoryTabType.Scientific}
									showTooltip={false}
									activateInfo={(playerId: PlayerId) => {
										if (ActionHandler.isTouchActive) {
											model.focusPlayer(playerId, VictoryTabType.Scientific);
											model.onGamepadInspectButton();
										}
									}}
								>
									<div
										class="flex-auto flex flex-row h-32"
										onMouseEnter={() => {
											player.playerInfo.setHighlighted(true);
										}}
										onMouseLeave={() => {
											player.playerInfo.setHighlighted(false);
										}}
									>
										<div class="flex flex-col justify-center">
											<Divider.Vertical
												class="-translate-x-1\/2"
												length="3\/4"
												color="rgba(255, 255, 255, 0.6)"
											/>
										</div>
										<div class="w-22" />
										<PointsBarComponent
											playerDetail={player}
											pointsSectionHeaders={props.pointsSectionHeaders}
										/>
									</div>
									<Tooltip.Text
										header={launchpadProps().launchpadStatus.tooltipHeader}
										text={launchpadProps().launchpadStatus.tooltipText}
									>
										<Activatable
											class="victories-focusable-ticket w-23 flex items-center justify-center"
											onFocus={() => onFocus(player.playerInfo.playerId)}
											onBlur={() => onBlur(player.playerInfo.playerId)}
										>
											<CardFrame class="size-20 flex items-center justify-center ml-3">
												<LaunchpadDisplayComponent {...launchpadProps()} />
											</CardFrame>
										</Activatable>
									</Tooltip.Text>
								</VictoryRow>
							</VSlot>
						);
					}}
				</For>
			</VSlot>
		</VictoryTabBase>
	);
};

export const ScienceVictoryTab = ComponentRegistry.register({
	name: "ScienceVictoryTab",
	createInstance: ScienceVictoryTabComponent,
});
//#endregion
